            Reservation reservation = reservationService.createReservation(
                    request.getRoomNumber(),
                    request.getGuestName(),
                    request.getGuestEmail(),
                    request.getGuestCpf(),
                    checkIn,
                    checkOut,
                    request.getGuests(),
                    ratePlan
            );

